import { optList } from "@/api/system/devInBound";
export default {
  props: ['infoList', 'serialNumber'],
  data: function data() {
    return {
      searchForm: {
        current: 1,
        size: 20
        // needAction: false,
        // needActionType: false,
      },
      dataList: [],
      selectionList: [],
      total: 0,
      tableLoading: false,
      //表格加载
      tableHeight: null
    };
  },
  computed: {
    ids: function ids() {
      var ids = [];
      this.selectionList.forEach(function (ele) {
        ids.push(ele.id);
      });
      return ids.join(",");
    }
  },
  mounted: function mounted() {
    var _this = this;
    setTimeout(function () {
      _this.getList();
    }, 800);
  },
  methods: {
    getList: function getList() {
      var _this2 = this;
      this.tableLoading = true;
      this.searchForm.logId = this.serialNumber;
      optList(this.searchForm).then(function (res) {
        _this2.dataList = res.data.records;
        _this2.total = res.data.total;
        _this2.tableLoading = false;
      });
    },
    selectionChange: function selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(function (item) {
        return item.id;
      });
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        var items = dictList.filter(function (item) {
          return item.dictKey == code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    }
  },
